  {"site": "Models.Cards/Pinpoint.cs:128", "entry": "CardPlayFinished", "agg": "count", "window": "this_turn", "filter": "Card.Type == Skill && CardPlay.Player == Owner", "use": "cost reduction when entering combat"},
