  {"site": "Models.Cards/ThrummingHatchet.cs:57", "entry": "CardPlayFinished", "agg": "any", "window": "last_player_turn", "filter": "CardPlay.Card == this card instance", "use": "trigger at player turn start"},
  {"site": "Models.Cards/Voltaic.cs:140", "entry": "OrbChanneled", "agg": "count", "window": "combat", "filter": "Actor.Player == Owner && Orb is LightningOrb", "use": "CalculatedChannels multiplier"},
