  {"site": "Models.Powers/FeralPower.cs:35", "entry": "CardPlayStarted", "agg": "count", "window": "this_turn", "filter": "Card.Type == Attack && CardPlay.Player == Owner.Player && Resources.EnergyValue == 0", "use": "initialise counter on AfterApplied"},
  {"site": "Models.Powers/IterationPower.cs:59", "entry": "CardDrawn", "agg": "count", "window": "this_turn", "filter": "Actor == Owner && Card.Type == Status", "use": "draw when count <= 1"},
  {"site": "Models.Powers/JugglingPower.cs:122", "entry": "CardPlayStarted", "agg": "count", "window": "this_turn", "filter": "Card.Type == Attack && CardPlay.Player == Owner.Player", "use": "initialise counter on AfterApplied"},
